-- Tenant registry (Phase 4 Group 1; decision log §18).
--
-- tenants is PLATFORM-OWNED and GLOBAL: one row per client business (tenant). It is not a
-- tenant-owned table, so it has no tenant_id column and no row-level security policy; the RLS
-- catalog guard applies only to tables with a tenant_id column (testing standards §6).
--
-- Retention class: account. The retention PERIOD is not defined; it is subject to legal review
-- (AGENTS.md §10.8). Nothing here expires or deletes tenants.
--
-- Columns:
--   id            UUIDv7 generated by PostgreSQL 18's built-in uuidv7() (owner decision: no UUID
--                 library). Time-ordered, so new rows append to the primary-key index.
--   display_name  A label for operators. NOT unique: no requirement establishes that two tenants
--                 cannot share a name. Trimmed, 1 to 200 characters, no control characters (the
--                 length bound is an engineering limit, not a business rule).
--   status        pending (created, not yet active) | active | suspended. Allowed transitions are
--                 enforced by the tenancy repository: pending -> active, active -> suspended,
--                 suspended -> active.
--   created_at, updated_at  timestamptz, set by the database.
-- created_by / updated_by are deferred until authenticated actors exist (owner decision).
--
-- Privileges: the table is owned by the migration role (sms_migrator). The application role
-- (sms_app) gets only what the tenancy repository needs, column by column: it can read every
-- column, insert only display_name (id, status and timestamps always come from the defaults), and
-- update only status and updated_at. No DELETE, no TRUNCATE.
--
-- Rollback: the Down section drops the table and every tenant row with it. It exists for local
-- development and tests only (`migrate down` is refused outside them); production migrations are
-- forward-only (AGENTS.md §10.1).

-- +goose Up
CREATE TABLE tenants (
    id           uuid        NOT NULL DEFAULT uuidv7(),
    display_name text        NOT NULL,
    status       text        NOT NULL DEFAULT 'pending',
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT pk_tenants PRIMARY KEY (id),
    CONSTRAINT ck_tenants__status CHECK (status IN ('pending', 'active', 'suspended')),
    CONSTRAINT ck_tenants__display_name CHECK (
        display_name = btrim(display_name)
        AND char_length(display_name) BETWEEN 1 AND 200
        AND display_name !~ '[[:cntrl:]]'
    ),
    CONSTRAINT ck_tenants__updated_at CHECK (updated_at >= created_at)
);

COMMENT ON TABLE tenants IS
    'Platform-owned tenant registry (no tenant_id, no RLS). Retention class: account; period undefined, subject to legal review.';

GRANT SELECT ON tenants TO sms_app;
GRANT INSERT (display_name) ON tenants TO sms_app;
GRANT UPDATE (status, updated_at) ON tenants TO sms_app;

-- +goose Down
DROP TABLE tenants;
